// キーは原資料の地域名。時代によって別政権を指す名称は下で解決する。
const studyProfiles = new Map();
function profile(keys, period, founder, place, lesson) {
  const card = {period, founder, place, lesson};
  for (const key of keys.split('|')) studyProfiles.set(key, card);
}
profile('Achaemenid Empire','前550年頃〜前330年','キュロス2世','イラン高原・西アジア','ダレイオス1世がサトラップを置き、王の道を整備。アレクサンドロスの遠征で滅亡した。');
profile('Empire of Alexander','前336〜前323年（アレクサンドロスの在位）','アレクサンドロス3世がマケドニア王国を継承し拡大','東地中海〜インダス川流域','前334年に東方遠征を開始。大王の死後、後継者たちが領土を争った。');
profile('Seleucid Kingdom','前312〜前63年','セレウコス1世','シリア・西アジア','アレクサンドロスの後継諸国の一つ。前63年にポンペイウスがシリアをローマの属州とした。');
profile('Ptolemaic Kingdom','前305〜前30年（王朝）','プトレマイオス1世','エジプト・アレクサンドリア','最後の女王はクレオパトラ7世。前31年のアクティウムの海戦の翌年、エジプトはローマの支配下に入った。');
profile('Rome|Roman Republic','前509年頃〜前27年（共和政）','王政を倒したローマ人。ブルトゥスは伝承上の中心人物','イタリア・ローマ','ポエニ戦争を経て地中海に進出。前27年にオクタウィアヌスがアウグストゥスの称号を受けた。');
profile('Roman Empire|Rome (Constantinus)|Rome (Maximian)|Rome (Galerius)|Rome (Diocletianus)','前27年〜395年（東西分割まで）','アウグストゥス（初代皇帝）','地中海世界','帝政後期には四帝分治が行われた。395年の分割後、西の皇帝位は476年に消滅し、東の帝国は1453年まで続いた。');
profile('Western Roman Empire','395〜476年（東西分割後）','ホノリウス（分割後の初代西方皇帝）','イタリアと西地中海','476年、オドアケルが西方皇帝ロムルス＝アウグストゥルスを退位させた。');
profile('Eastern Roman Empire|Byzantine Empire','395〜1453年（東西分割を起点とする）','アルカディウス（分割後の初代東方皇帝）','コンスタンティノープル','ユスティニアヌス帝が『ローマ法大全』を編纂させた。1453年に都がオスマン帝国に陥落。');
profile('Parthian Empire','前247年頃〜後224年','アルサケス1世','イラン・メソポタミア','東西交易の中継を担い、ローマと対抗した。ササン朝の成立で滅亡。');
profile('Sasanian Empire','224〜651年','アルダシール1世','イラン・クテシフォン','ゾロアスター教を保護し、東ローマと抗争。7世紀のアラブ勢力の征服で滅亡。');
profile('Mauryan Empire','前317〜前180年頃。前321〜前185年頃などの説もある','チャンドラグプタ','北インド・パータリプトラ','アショーカ王はカリンガ征服後、ダルマによる統治を掲げ、磨崖碑・石柱碑を残した。');
profile('Gupta Empire','320年頃〜550年頃','チャンドラグプタ1世が王朝の基礎を確立','北インド','チャンドラグプタ2世の時代に法顕が来訪。サンスクリット文学が栄えた。');
profile('Kushan Empire','紀元1〜3世紀頃が中心（年代に諸説）','クジュラ＝カドフィセスが勢力を統合','中央アジア南部・北西インド','カニシカ王が仏教を保護。ガンダーラ美術と東西交易を結びつけよう。');
