const demiseByProfile = new Map();
function demise(keys, explanation) {
  for (const key of keys.split('|')) {
    const card = studyProfiles.get(key);
    if (card) demiseByProfile.set(card, explanation);
  }
}
demise('Achaemenid Empire','アレクサンドロスの遠征で軍事的敗北を重ねた。前330年にダレイオス3世が殺害され、王朝が終わった。');
demise('Empire of Alexander','前323年の大王の死後、統一した継承体制を確立できず、ディアドコイの争いで帝国が分裂した。');
demise('Seleucid Kingdom','王位継承争いや領土喪失で弱体化し、前63年にポンペイウスがシリアをローマの属州にした。');
demise('Ptolemaic Kingdom','オクタウィアヌスとの抗争に敗れた。前30年にアントニウスとクレオパトラが死去し、エジプトはローマに併合された。');
