const historyCatalogue=[];
function addHistory(id,label,region,aliases,start,end,founder,capitalsText,lesson,ending,capitals=[],period='') {
  historyCatalogue.push({id,label,region,aliases:aliases.split('|').filter(Boolean),start,end,
    period:period||((start<0?'前'+(-start):start)+'年〜'+(end===9999?'':(end<0?'前'+(-end):end)+'年')),
    founder,place:capitalsText,lesson,ending,capitals});
}
function reuseHistory(key,id,label,region,aliases,start,end,capitalsText,capitals=[]){
  const info=studyProfiles.get(key);
  if(!info)throw new Error('Missing study profile '+key);
  addHistory(id,label,region,aliases,start,end,info.founder,capitalsText,info.lesson,demiseByProfile.get(info)||'',capitals,info.period);
}
