addHistory('brazil','ブラジル',AM,'Brazil|Kingdom of Brazil',1822,9999,'ペドロ1世（独立時の皇帝）','リオデジャネイロ、1960年からブラジリア','ポルトガルから帝政として独立。1888年の奴隷制廃止、1889年の共和政移行。','国家として存続。1889年に軍部の政変で帝政が終わった。',[['リオデジャネイロ',-43.17,-22.91,1822,1959],['ブラジリア',-47.88,-15.79,1960,9999]]);

const historicalAudit={"shang":{"note":"建国・滅亡は概数。前1600・前1046は実装上の代表値であり、確定年として暗記しない。収録地図の前500年より古い。","sources":["shang"]},"zhou":{"note":"前11世紀頃の成立、前256年の王室滅亡を区別。Zhou states は周王の直轄領ではなく諸侯を含む。","sources":["zhou"]},"qin":{"note":"前770年は諸侯国段階の目安。統一王朝は前221〜前206年（前207年終期説もある）。","sources":["qin"]},"han":{"note":"前202年は劉邦の皇帝即位基準。漢王封建を起点に前206年とする資料もある。新は9〜23年、その後の混乱を経て25年に後漢成立。","sources":["han"]},"sanguo":{"note":"220〜280年は時代全体。魏220〜265、蜀221〜263、呉229〜280を別々に判定する。","sources":["sanguo"]},"jin":{"note":"西晋265〜316、東晋317〜420。原資料の500年図にある Jin Empire は晋の期間外で、晋として採用しない。","sources":["chinaEarly"]},"nwei":{"note":"386〜534年。孝文帝の洛陽遷都は494年。三国の魏、女真の金とは別の王朝。","sources":["nwei"]},"sui":{"note":"581〜618年、統一は589年。700年図の Sui Empire は原資料の年代不整合として領域を省く。","sources":["sui"]},"tang":{"note":"618〜907年の間に武周690〜705年を挟む。武周期を隋や唐の領域で代用しない。","sources":["zhou","sui"]},"song":{"note":"960〜1279年。1127年に北宋から南宋へ移行。宋の領域を中国全土と同一視しない。","sources":["chinaMiddle"]},"liao":{"note":"皇帝即位916年を採用。907年成立とする資料もあり、遼の国号使用と混同しない。","sources":["liao","chinaMiddle"]},"jurchenjin":{"note":"1115〜1234年。女真の王朝であり、265〜420年の晋と別。収録地図の Jin は晋を指す。","sources":["chinaMiddle"]},"yuan":{"note":"国号制定1271年と南宋滅亡1279年を区別。1368年は中国支配の終わりで、北元は存続。","sources":["chinaMiddle"]},"ming":{"note":"1368〜1644年は北京陥落まで。南明・鄭氏政権まで一律に1644年で消滅したと解釈しない。","sources":["chinaMiddle","qing"]},"qing":{"note":"後金1616、清の国号1636、北京入城1644、退位1912。1914年図の Manchu Empire は清として採用しない。","sources":["qing"]},"roc":{"note":"1912年成立、1949年に政府が台湾へ移転。1949年以降の大陸の China を中華民国カードへ結び付けない。","sources":["roc","prc"]},"prc":{"note":"1949年10月成立。1945年図の China の輪郭をそのまま中華人民共和国の領土と解釈しない。","sources":["prc"]},"goguryeo":{"note":"前37年は建国伝承、滅亡668年。700年図の Koguryo は期間外として扱う。","sources":["koreaEarly"]},"baekje":{"note":"前18年は建国伝承、660年に本国滅亡。663年の復興運動敗北と区別。700年図の Paekche は期間外。","sources":["koreaEarly"]},"silla":{"note":"統一前の段階として676年より前を表示。新羅国家そのものが676年に滅びたわけではない。","sources":["koreaEarly"]},"usilla":{"note":"676〜935年の統一期。半島全域の統一を意味せず、北に渤海が存在した。","sources":["koreaEarly","koreaMiddle"]},"balhae":{"note":"698年建国と713年の渤海郡王冊封を区別。926年に契丹の征服。","sources":["balhae"]},"goryeo":{"note":"918〜1392年。936年の後三国統一、1232年の江華遷都を別の事件として理解する。","sources":["koreaMiddle"]},"joseon":{"note":"1897年を国号変更の区切りとして採用。王朝自体の終わりを1910年とする資料と矛盾しない。","sources":["koreaMiddle"]},"japan":{"note":"600は地図照合の下限の目安で、建国年ではない。都・幕府・国家の領域を区別。鎌倉幕府は1333年に終わる。","sources":["japan"]},"rok":{"note":"1948年成立。朝鮮戦争中の政府所在地移転と、ソウルの首都としての地位を区別する。","sources":["koreaModern"]},"dprk":{"note":"1948年成立。1953年は休戦であり、平和条約による戦争終結年ではない。","sources":["koreaModern"]},"xiongnu":{"note":"単一の終年では捉えられない。48年南北分裂、北方の衰退と南匈奴の216年までの政権を分ける。","sources":["xiongnu"]},"xianbei":{"note":"1〜3世紀は連合勢力の目安。300年に民族が消滅したという意味ではなく、諸集団と北魏などが続く。","sources":["xianbei"]},"gokturk":{"note":"東突厥630、西突厥657、第二可汗国682〜744を区別。700年図の西突厥を第二可汗国の領土へ読み替えない。","sources":["gokturk"]},"uyghur":{"note":"744〜840年はモンゴル高原の可汗国。840年以降の西遷・後継政権と民族の活動は続く。","sources":["centralEarly","centralMiddle"]},"tibet":{"note":"7〜9世紀半ばの統一王国。600・842は表示用の代表値で、形成・分裂の過程を1年に固定しない。","sources":["tibet"]},"mongol":{"note":"1206年成立、1260年頃から分裂が進む統一帝国期として登録。1200年の帝国名を採用しない。","sources":["mongol"]},"chagatai":{"note":"1227年は分封の目安。14世紀半ばの東西分裂、西部の1370年頃の転換、東方の後継国家を区別。","sources":["chagatai"]},"kipchak":{"note":"1236〜41年の征服、1243年頃の政権形成を区別し、建国の目安を1243に修正。1502年は大オルダの終わり。","sources":["kipchak"]},"ilkhan":{"note":"1256〜1335年は統合政権を基準。1258年建国説や1353年までの名目的ハン位を含める区分もある。","sources":["centralMiddle","ilkhan"]},"timur":{"note":"1370〜1507年は王朝全体。1405年のティムール死去、以後の王家分立、1507年ヘラート陥落を区別。","sources":["timur"]},"sumer":{"note":"都市国家群で統一国家ではない。前4千年紀後半〜前2千年紀初頭の代表範囲で、前2004年はウル第三王朝の終わり。","sources":["mesoEarly"]},"oldbab":{"note":"バビロン第一王朝の範囲。前1894〜前1595は中年代による数値で、古バビロニア時代全体とは別。","sources":["mesoBronze"]},"hittite":{"note":"前17〜前12世紀頃。前1650・前1180は近似値で、後継の新ヒッタイト諸国と区別。","sources":["hittite"]},"assyria":{"note":"前2千年紀初頭からの長期史。前612年のニネヴェ陥落と前609年までの残存勢力を区別する。","sources":["assyria","mesoIron"]},"neobab":{"note":"前626（前625説）〜前539年。建国年に1年差のある資料があり、前539年の征服を重視。","sources":["mesoIron","neobab"]},"achaemenid":{"note":"前550年頃〜前330年。キュロスのメディア征服と、アレクサンドロスによる王朝終焉を基準。","sources":["iranAncient"]},"seleucid":{"note":"前312はセレウコス紀元の起点で、王号採用は前305頃。イラン支配の終わりと前63年の王朝終焉は異なる。","sources":["iranAncient","seleucid"]},"parthia":{"note":"前247年頃〜224年。300年図の Parthian Empire は期間外。アルサケス朝とササン朝を区別する。","sources":["iranAncient","centralEarly"]},"sasanian":{"note":"224〜651年。700年図の Sasanian Empire は期間外。651年は最後の王ヤズデギルド3世の死を基準。","sources":["centralEarly","iranEarly"]},"rashidun":{"note":"632〜661年。預言者ムハンマドの在世期や、地域ごとの征服・支配開始年とは区別する。","sources":["islam"]},"umayyad":{"note":"661〜750年はダマスクスを中心とした王朝。イベリアの後ウマイヤ朝756〜1031とは別。","sources":["islam"]},"abbasid":{"note":"750〜1258年はバグダード系カリフ政権。地方の独立、ブワイフ朝・セルジューク朝の実権と区別。","sources":["islam","iranMiddle"]},"cordoba":{"note":"756年首長国、929年カリフ国、1031年解体。時期に合った日本語名を使い分ける。","sources":["islam"]},"fatimid":{"note":"909〜1171年。969年のエジプト征服と973年のカイロ遷都を区別。1200年図は期間外。","sources":["fatimid","egyptMiddle"]},"seljuk":{"note":"1038年頃〜1194年は広義の王朝区分。1157年以後の分立、ルーム・セルジューク朝とは区別。","sources":["seljuk","iranMiddle"]},"ayyubid":{"note":"1171〜1250年はエジプト、1260年頃はシリア主力諸家の転換。さらに後まで存続する傍系もある。","sources":["egyptMiddle","eastMedMiddle"]},"mamluk":{"note":"1250〜1517年。アイン＝ジャールート1260と、オスマンによるエジプト征服1517を区別。","sources":["egyptMiddle","islam"]},"ottoman":{"note":"1299年頃は伝統的な建国の目安。1922年スルタン制廃止と1923年トルコ共和国成立を区別。 1530年図のタブリーズ周辺は国境データに不整合があり要再作図。","sources":["ottoman","safavidBoundary"]},"safavid":{"note":"1501〜1736年。1722年イスファハーン陥落と、1736年ナーディルの即位を区別。 1530年図ではタブリーズがオスマン領に入っており、この国境は史実との不整合がある。","sources":["safavid","safavidBoundary"]},"athens":{"note":"前8世紀頃のポリス形成、前322年の民主政制限を区切りに採用。都市の消滅年ではない。","sources":["athens"]},"sparta":{"note":"前8世紀頃の形成〜ローマ支配への移行を扱う便宜的期間。前146年を都市・文化の消滅と解釈しない。","sources":["sparta"]},"macedon":{"note":"前7世紀頃〜前168年は王国史。アレクサンドロス帝国の最大領域がこの全期間に存在したわけではない。","sources":["macedon"]},"romanrep":{"note":"前509年は伝統的な共和政開始年、前27年は元首政への画期。前27年以前のローマを帝国に読み替えない。","sources":["rome"]},"romanemp":{"note":"前27〜395年は分割前という区分。395年はローマ国家全体の消滅年ではない。","sources":["rome"]},"byzantine":{"note":"395〜1453年を採用。1204〜1261年の亡命政権は、ラテン帝国による都の支配と区別する。 1400年図には都周辺の飛び地の欠落がある。","sources":["rome","byzantineBoundary"]},"frank":{"note":"481年頃はクローヴィスの即位の目安。751年王朝交替、843年分割を区切りとし、フランク人の終年にしない。","sources":["frank"]},"westfrank":{"note":"843〜987年はヴェルダン分割からカペー朝成立までの区分。境界は後世のフランスと一致しない。","sources":["westfrank"]},"eastfrank":{"note":"843〜962年を地図上の区分に採用。911年の王統断絶、919年のザクセン朝成立も別の区切り。","sources":["eastfrank","hre"]},"hre":{"note":"962〜1806年を高校世界史の代表的区分として維持。800年起源説と、諸領邦の自立に注意。","sources":["hre"]},"england":{"note":"927年の統一を起点とし、1707年の合同まで。1707年以降のイギリス全体と区別。","sources":["england","britain"]},"franceking":{"note":"987〜1792年は革命前の王政を扱うカード。復古王政と七月王政は近代フランスのカードで扱う。","sources":["capet","france"]},"venice":{"note":"697年は初代ドージェの伝承。中世初期の段階的成立と1797年の共和国崩壊を区別。","sources":["venice"]},"spain":{"note":"1479年は王朝連合の画期。共和国・独裁の時期にも王国と表示しないよう、国家史カード名をスペインへ修正。","sources":["spain","iberia"]},"portugal":{"note":"1139年の王号を起点に採用し、1143年の承認、1179年の教皇承認と区別。1910年は王政廃止。","sources":["iberia"]},"britain":{"note":"1707年合同、1801年アイルランド合同、1927年の国号変更を区別。帝国の植民地と本国を混同しない。","sources":["britain"]},"france":{"note":"1792年以降の国家史として扱い、帝政・復古王政期を共和国の存続と取り違えない。","sources":["france"]},"prussia":{"note":"1701〜1918年は王国の期間。1871年以降はドイツ帝国内の邦で、1918年以降の州とは区別。 1715年図のベルリンは Brandenburg（SUBJECTO: Prussia）の別領域として収録。","sources":["prussia"]},"austria":{"note":"1804年の皇帝号と帝国成立、1867年の二重帝国への改組を区別。ハプスブルク家支配はこれより古い。 原図1715年の Austrian Empire は帝国建国前であり、ハプスブルク家領という表記へ補正。","sources":["austria"]},"austriahungary":{"note":"1867〜1918年。Austria Hungary という原資料の別表記も同じカードに対応させる。","sources":["austriahungary"]},"germanemp":{"note":"1871〜1918年。Germany という名称は帝政以外でも使われるため、王朝の期間外はドイツとして残す。","sources":["germany"]},"russianemp":{"note":"1721〜1917年は皇帝号を基準とする帝国。以前のロシア国家、1917年以後の政府とは区別。","sources":["russia"]},"ussr":{"note":"1922〜1991年。1920年図の USSR を1922年成立の連邦領土として採用しない。革命1917年とも別。","sources":["ussr","russia"]},"nazigermany":{"note":"1933〜1945年は政権の期間。1933年のドイツと1938〜42年の拡大領域は同一ではない。","sources":["nazi"]},"italy":{"note":"1861〜1946年は王国。1960年以降の Italy を王国カードに結び付けず、イタリアとして残す。","sources":["italy"]},"poland":{"note":"966は国家形成の代表値。1795〜1918年の独立中断中にもワルシャワ公国・ポーランド王国などの政体がある。","sources":["poland"]},"yugoslavia":{"note":"1918〜2003は国名・国家群をまとめた区分。社会主義連邦の解体1991〜92と新連邦の改称2003を区別。","sources":["yugoslavia"]},"maurya":{"note":"前317〜前180頃は実在する年代説。前321〜前185頃や山川の前321〜前181頃もあり、誤記として一律に置換しない。","sources":["mauryaJapan","maurya"]},"kushan":{"note":"1〜3世紀中心という概数を維持。前100年図の帝国名、500年図の後継諸勢力を本朝と同一視しない。","sources":["kushan"]},"gupta":{"note":"320年頃〜550年頃。初期創始者シュリーグプタと、王権を強めたチャンドラグプタ1世を区別。","sources":["gupta"]},"vardhana":{"note":"606〜647年はハルシャの治世を基準。前身の家系全体や、北インド全域の直接統治を意味しない。","sources":["vardhana"]},"delhi":{"note":"1206〜1526年は五王朝の総称。1330年頃の最大領域を全期間の領土として扱わない。","sources":["delhi"]},"mughal":{"note":"1526〜1858年の間にスール朝1540〜1555年の中断がある。1530年図で中断期をムガル支配と表示しない。","sources":["mughal"]},"britishindia":{"note":"1858〜1947年は直接統治。1877年のインド皇帝号と、1911年のデリー遷都決定を区別。","sources":["india"]},"india":{"note":"1947年独立と1950年共和国成立を区別。1945年図の輪郭は独立インドの領土として認証しない。","sources":["india"]},"pakistan":{"note":"1947年独立、1956年共和国。1945年図の Pakistan は建国前の名称不整合。東部は1971年に独立。","sources":["pakistan"]},"funan":{"note":"1〜6／7世紀頃と資料に幅がある。600年は実装上の代表的終期で、確定した滅亡年ではない。","sources":["funan"]},"khmer":{"note":"802〜1431年はアンコール期の目安。1431年以後もカンボジアの王統・国家は続く。","sources":["southeastMiddle"]},"champa":{"note":"192年は林邑成立の伝承的起点。1471年の主要王都陥落、1832年の残存政権併合、1835年終期説を区別。","sources":["champa"]},"daiviet":{"note":"1054〜1804年頃は大越の国号。1400〜1407年の大虞と1407〜1427年の明支配を中断として扱う。","sources":["daiviet"]},"pagan":{"note":"1044年はアノーヤター即位。1287年は主要な転換、王朝終期を1299年とする資料もあるため併記。","sources":["pagan"]},"ayutthaya":{"note":"1351〜1767年の王国史。1569年のビルマ征服と16世紀末の独立回復を区別。","sources":["ayutthaya"]},"srivijaya":{"note":"7〜13世紀頃の中心期と14世紀の後継勢力を区別。1400は便宜的な上限で、確定滅亡年ではない。","sources":["southeastEarly","srivijaya"]},"majapahit":{"note":"1293年成立、終期は15世紀末〜16世紀前半に諸説。1527を確定年としない。","sources":["majapahit"]},"malacca":{"note":"1400年頃成立、1511年港市陥落。王家の後継勢力やポルトガル支配の港市とは別。","sources":["malacca"]},"egypt":{"note":"前3000年頃〜前332年は長期の文明・王権史。分裂期・ペルシア支配を一続きの独立国家としない。","sources":["egypt","ptolemy"]},"ptolemy":{"note":"前305〜前30年は王号採用からローマ併合まで。アレクサンドロスの前332年征服とは別。","sources":["ptolemy"]},"carthage":{"note":"前814年は建設伝承、前146年は第三次ポエニ戦争の都市破壊。後のローマ都市と区別。","sources":["carthage"]},"aksum":{"note":"紀元前後〜10世紀頃に幅のある区分。100・900は代表値で、7世紀以降の衰退と突然の滅亡を混同しない。","sources":["aksum"]},"ghana":{"note":"7世紀頃〜1240年頃という資料に合わせ、従来の1200年上限を1240年頃へ補正。現代ガーナとは場所が異なる。","sources":["ghana"]},"mali":{"note":"1235年頃の成立〜16世紀頃の中心期。帝国縮小後も王権が続くため、1600を絶対的終年としない。","sources":["mali"]},"songhai":{"note":"1464〜1591年は帝国期。1591年以後の Songhai は後継・地域勢力として扱い、帝国カードへ結び付けない。","sources":["songhai"]},"ethiopia":{"note":"1270〜1974年はソロモン朝中心の帝国史。1936〜1941年の占領中にも亡命皇帝が存在した。","sources":["ethiopia"]},"zulu":{"note":"1816〜1879年は独立王国、1897年はナタール編入。図鑑内の数値と説明がずれないよう段階を明記。","sources":["zulu"]},"maya":{"note":"文明・都市国家群で統一国家ではない。1697年は最後の主要独立王国征服で、民族・文化は現在にも続く。","sources":["maya"]},"aztec":{"note":"1428〜1521年は三都市同盟。1325年のテノチティトラン建設と帝国成立を区別。","sources":["aztec"]},"inca":{"note":"1438年頃〜1533年は帝国拡大からクスコ陥落まで。1532年の皇帝捕縛、1572年の最後の抵抗政権を区別。","sources":["inca"]},"usa":{"note":"1776年独立宣言、1783年イギリス承認。各時代の領土獲得を区別し、現代の輪郭で創設時を代用しない。","sources":["usa"]},"haiti":{"note":"1804年独立。トゥサンと独立を宣言したデサリーヌを区別し、独立後の分裂期も考慮。","sources":["haiti"]},"mexico":{"note":"1810年運動開始と1821年独立達成を区別。帝政・共和政と米墨戦争による領土変化に注意。","sources":["latin"]},"brazil":{"note":"1822年独立、1888年奴隷制廃止、1889年共和政。1960年のブラジリア遷都を区別。","sources":["latin"]}};
