// Inclusive annual ranges; transition years may contain both governments.
const historicalInterruptions={han:[[9,24]],tang:[[690,704]],poland:[[1795,1917]],mughal:[[1540,1554]],daiviet:[[1400,1427]],gokturk:[[658,681]]};
const aliasPeriods={
  Wei:[220,265], 'Cao Wei':[220,265], Shu:[221,263], 'Shu Han':[221,263],
  Wu:[229,280], 'Eastern Wu':[229,280],
  'Western Gokturk Khaganate':[552,657], 'Eastern Turks':[552,630],
  Xiongnu:[-209,155], 'Southern Xiongnu':[48,216], 'S. Xiongnu':[48,216]
};
function isActive(entry,year){
  if(year<entry.start||year>entry.end)return false;
  if((historicalInterruptions[entry.id]||[]).some(([from,to])=>year>=from&&year<=to))return false;
  if(entry.id==='silla')return year<676;
  return true;
}
function aliasActive(entry,n,year){
  if(!isActive(entry,year))return false;
  if(n==='Eastern Turks'&&year>=682&&year<=744)return true;
  const range=aliasPeriods[n];
  if(range&&(year<range[0]||year>range[1]))return false;
  if(n==='China'&&entry.id==='roc'&&year>=1949)return false;
  return true;
}
function sameHistoricalEpisode(entry,a,b){
  return !(historicalInterruptions[entry.id]||[]).some(([from,to])=>Math.min(a,b)<=to&&Math.max(a,b)>=from);
}
function findHistory(feature,year){
  const n=name(feature),base=feature.mapYear??year;
  return (catalogueByAlias.get(n)||[])
    .filter(entry=>aliasActive(entry,n,year)&&aliasActive(entry,n,base)&&sameHistoricalEpisode(entry,base,year))
    .sort((a,b)=>b.start-a.start)[0]||null;
}
function datedName(feature,year){
  const n=name(feature),entry=findHistory(feature,year);
  if(entry?.id==='han')return year<9?'前漢':'後漢';
  if(entry?.id==='song')return year<1127?'北宋':'南宋';
  if(entry?.id==='britain'&&n!=='British Empire')return year<1801?'グレートブリテン王国':year<1927?'グレートブリテン及びアイルランド連合王国':'イギリス';
  if(entry?.id==='cordoba')return year<929?'後ウマイヤ朝（首長国）':'後ウマイヤ朝（カリフ国）';
  if(entry?.id==='qin')return year < -221?'秦（諸侯国）':'秦（統一王朝）';
  if(n==='Poland'&&year>=1795&&year<1918)return 'ポーランド地域（分割期）';
  return entry?.label||independentNames[n];
}
function dateFeatures(features,year){
  return features.filter(f=>(f.properties.FROM==null||(f.properties.FROM<=year&&year<=f.properties.TO))&&(!catalogueByAlias.has(name(f))||findHistory(f,year)||Object.hasOwn(independentNames,name(f))));
}
