function cityRecord(row,entry=null,reference=false){
  return {name:row[0],lng:row[1],lat:row[2],from:row[3],to:row[4],
    role:row[5]||(entry?'都':'主要都市'),entry,reference,capital:row[5]!=='主要都市'&&(!!entry||/都|政治拠点|王廷/.test(row[5]||''))};
}
function citiesForYear(year){
  const points=[];
  {
    for(const entry of historyCatalogue){
      if(!isActive(entry,year))continue;
      for(const row of entry.capitals){
        const point=cityRecord(row,entry);
        if(year>=row[3]&&year<=row[4]&&$(point.capital?'capitals':'cities').checked)points.push(point);
      }
    }
  }
  if($('capitals').checked&&year>=690&&year<705)
    points.unshift(cityRecord(['洛陽（武周）',112.45,34.68,690,704,'武周の都']));
  if($('cities').checked){
    for(const row of mainCities)if(year>=row[3]&&year<=row[4])points.push(cityRecord(row));
  }
  if($('capitals').checked&&referenceCapital)points.unshift(referenceCapital);
  const unique=new Map();
  for(const point of points){
    const key=point.lng.toFixed(2)+','+point.lat.toFixed(2)+','+point.name;
    if(!unique.has(key))unique.set(key,point);
  }
  return [...unique.values()].sort((a,b)=>
    Number(!!activeHistory&&b.entry?.id===activeHistory.id)-Number(!!activeHistory&&a.entry?.id===activeHistory.id)||
    Number(b.reference)-Number(a.reference)||Number(!!b.entry)-Number(!!a.entry));
}
function drawCities(){
  cityScreenPoints=[];cityLabelBoxes=[];
  const center=[-projection.rotate()[0],-projection.rotate()[1]];
  let labelled=0;
  for(const point of citiesForYear(requested)){
    if(!flat&&d3.geoDistance([point.lng,point.lat],center)>Math.PI/2-.01)continue;
    const p=projection([point.lng,point.lat]);
    if(!p||!p.every(Number.isFinite)||p[0]<8||p[0]>width-8||p[1]<90||p[1]>height-52)continue;
    const item={...point,x:p[0],y:p[1]};
    cityScreenPoints.push(item);
    const highlighted=point.reference||!!activeHistory&&point.entry?.id===activeHistory.id;
    ctx.save();ctx.fillStyle=point.reference?'#ffdeb0':point.capital?'#ffd78e':'#89dcdf';
    ctx.strokeStyle='#07141e';ctx.lineWidth=2;
    if(point.capital){
      const radius=highlighted?6:4.5;
      ctx.beginPath();
      for(let i=0;i<10;i++){
        const angle=-Math.PI/2+i*Math.PI/5,r=i%2?radius*.43:radius;
        const x=p[0]+Math.cos(angle)*r,y=p[1]+Math.sin(angle)*r;
        if(i===0)ctx.moveTo(x,y);else ctx.lineTo(x,y);
      }
      ctx.closePath();ctx.stroke();ctx.fill();
    }else{ctx.beginPath();ctx.arc(p[0],p[1],3,0,2*Math.PI);ctx.stroke();ctx.fill();}
    ctx.font=(highlighted?'600 ':'')+'11px system-ui';
    const text=(point.reference?'参照・':'')+point.name,w=ctx.measureText(text).width;
    const left=Math.max(8,Math.min(width-w-8,p[0]+8));
    const box=[left-3,p[1]-9,w+6,18];
    if((highlighted||labelled<40)&&!cityLabelBoxes.some(b=>
      box[0]<b[0]+b[2]&&box[0]+box[2]>b[0]&&box[1]<b[1]+b[3]&&box[1]+box[3]>b[1])){
      ctx.textAlign='left';ctx.textBaseline='middle';ctx.lineWidth=3;
      ctx.strokeStyle='#081720';ctx.strokeText(text,left,p[1]);ctx.fillText(text,left,p[1]);
      item.labelBox=box;cityLabelBoxes.push(box);labelled++;
    }
    ctx.restore();
  }
}
function cityAt(x,y){
  return cityScreenPoints.find(point=>Math.hypot(point.x-x,point.y-y)<9||
    (point.labelBox&&x>=point.labelBox[0]&&x<=point.labelBox[0]+point.labelBox[2]&&y>=point.labelBox[1]&&y<=point.labelBox[1]+point.labelBox[3]));
}
function possibleMapYears(entry){
  const aliases=entry.aliases.concat([...catalogueByAlias].filter(([,entries])=>entries.includes(entry)).map(([alias])=>alias));
  return [...new Set(aliases.flatMap(alias=>studyYears[alias]||[]))]
    .filter(year=>aliases.some(alias=>(studyYears[alias]||[]).includes(year)&&findHistory({properties:{NAME:alias},mapYear:year},year)?.id===entry.id)).sort((a,b)=>a-b);
}
function chooseHistory(entry){
  activeHistory=entry;referenceCapital=null;selectedCity=null;
  selected=current?.find(f=>findHistory(f,requested)?.id===entry.id)||null;
  const row=entry.capitals.find(c=>requested>=c[3]&&requested<=c[4])||entry.capitals[0];
  if(row){
    lon=row[1];lat=row[2];zoom=2;
    if(requested<row[3]||requested>row[4])referenceCapital=cityRecord(row,entry,true);
  }
  updateDetail();scheduleDraw();
}
function focusCapital(entry,index){
  const row=entry.capitals[index];
  referenceCapital=cityRecord(row,entry,requested<row[3]||requested>row[4]);
  lon=row[1];lat=row[2];zoom=Math.max(zoom,2);selectedCity=referenceCapital;
  updateDetail();scheduleDraw();
}
function selectCity(point){
  if(point.kind==='missingCountry'){chooseHistory(point.entry);return;}
  selectedCity=point;
  if(point.entry){
    activeHistory=point.entry;
    selected=current?.find(f=>findHistory(f,requested)?.id===point.entry.id)||null;
  }
  updateDetail();scheduleDraw();
}
function cataloguePanel(entry){
  const rows=[['存続年代・区分',entry.period],['建国者・成立の中心人物',entry.founder],['都・政治拠点',entry.place]];
  let result='<h3>'+escapeHtml(entry.label)+'</h3><dl class="study-facts">'+rows.map(([title,value])=>
    '<dt>'+title+'</dt><dd>'+escapeHtml(value)+'</dd>').join('')+'</dl>';
  result+='<h4>世界史のポイント</h4><p>'+escapeHtml(entry.lesson)+'</p>'+
    '<h4>滅亡・解体／その後</h4><p>'+escapeHtml(entry.ending)+'</p>';
  if(entry.capitals.length){
    result+='<h4>都と政治拠点の位置</h4><div class="capital-list">'+entry.capitals.map((row,index)=>
      '<button data-capital="'+index+'">'+(row[5]==='主要都市'?'● ':'★ ')+escapeHtml(row[0])+'<small>'+fmt(row[3])+'〜'+(row[4]===9999?'現在':fmt(row[4]))+(row[5]?' ／ '+escapeHtml(row[5]):'')+'</small></button>').join('')+'</div>';
  }
  if(entry.audit)result+='<h4>年代・史実の確認メモ</h4><p>'+escapeHtml(entry.audit.note)+'</p><p class="small">'+auditSourceLinks(entry.audit.sources)+'</p>'+geometryAuditSummary(entry.id);
  const mapYears=possibleMapYears(entry);
  if(!selected){
    result+='<p class="small">この国・王朝の領域は、現在の地図では選択されていません。地球儀上の「領域図なし」は、都の位置を使った国名表示であり、領土の復元図ではありません。</p>';
    if(mapYears.length)result+='<button data-history-jump="'+entry.id+'">この国の地図年代へ移動</button>';
    else result+='<p class="small">対応する領域データが未収録です。位置ボタンで都を参照できます。</p>';
  }
  if(referenceCapital?.reference)result+='<p class="small">「参照」の点は別年代の都の位置です。背景の地図は'+fmt(currentYear)+'を表示しています。</p>';
  return result;
}
function renderHistoryBook(){
  const query=$('search').value.trim().toLowerCase();
  const region=$('historyRegion').value;
  const entries=historyCatalogue.filter(entry=>(!region||entry.region===region)&&
    [entry.label,entry.region,...entry.aliases,...entry.capitals.map(row=>row[0])].join(' ').toLowerCase().includes(query));
  $('count').textContent=entries.length+' / '+historyCatalogue.length;
  const list=$('countryList');list.replaceChildren();
  for(const entry of entries){
    const button=document.createElement('button');
    button.textContent=entry.label;
    button.onclick=()=>chooseHistory(entry);
    list.append(button);
  }
  if(!entries.length)list.textContent='該当する国・都がありません。';
}
function wireHistoryPanel(){
  const panel=$('detail');
  panel.querySelectorAll('[data-capital]').forEach(button=>button.onclick=()=>focusCapital(activeHistory,+button.dataset.capital));
  const jump=panel.querySelector('[data-history-jump]');
  if(jump)jump.onclick=async()=>{
    const entry=activeHistory,available=possibleMapYears(entry);
    const year=available.reduce((best,y)=>Math.abs(y-requested)<Math.abs(best-requested)?y:best,available[0]);
    await setYear(year);chooseHistory(entry);
  };
}

function normalize(data){for(const f of data.features){const geom=f.geometry;if(!geom)continue;let polys=geom.type==='Polygon'?[geom.coordinates]:geom.type==='MultiPolygon'?geom.coordinates:[];for(let rings of polys){let outer={type:'Polygon',coordinates:[rings[0]]};if(d3.geoArea(outer)>2*Math.PI)rings[0].reverse();for(let hole of rings.slice(1)){if(d3.geoArea({type:'Polygon',coordinates:[hole]})<2*Math.PI)hole.reverse()}}f.center=d3.geoCentroid(f);f.area=d3.geoArea(f)}return data.features.filter(f=>f.geometry&&['Polygon','MultiPolygon'].includes(f.geometry.type)&&Number.isFinite(f.area)&&f.area>1e-12&&f.center.every(Number.isFinite)).sort((a,b)=>b.area-a.area)}
