  if(city||hovered){
    tip.textContent=city?(city.capital?'★ ':'● ')+city.name+' ／ '+city.role:jp(hovered)+' · '+fmt(currentYear);
    tip.style.left=Math.max(0,Math.min(x+15,width-240))+'px';
    tip.style.top=Math.max(0,Math.min(y+15,height-55))+'px';
  }
